@@ -32,6 +32,8 @@

 namespace TaskManager
 {
+constexpr qsizetype maxManualAppOrder = 50;
+
 class Q_DECL_HIDDEN TasksModel::Private
 {
 public:
@@ -61,6 +63,7 @@ public:
     QList<int> sortedPreFilterRows;
     QList<int> sortRowInsertQueue;
