@@ -408,6 +417,8 @@ void TasksModel::Private::updateManualSortMap()
         TasksModelLessThan lt(concatProxyModel, q, false);
         std::ranges::stable_sort(sortedPreFilterRows, lt);

+        applyManualAppOrder();
+
         // Consolidate sort map entries for groups.
         if (q->groupMode() != GroupDisabled) {
             for (int i = 0; i < groupingProxyModel->rowCount(); ++i) {
@@ -556,6 +567,111 @@ void TasksModel::Private::consolidateManualSortMapForGroup(const QModelIndex &gr
     }
 }

+QString TasksModel::Private::manualAppOrderId(const QModelIndex &concatProxyIndex) const
+{
+    // Launchers and tasks sorted as their launcher keep their place through the launcher list.
+    if (concatProxyIndex.data(AbstractTasksModel::IsLauncher).toBool()) {
+        return {};
+    }
+
+    if ((launchInPlace || !separateLaunchers) && q->launcherPosition(concatProxyIndex.data(AbstractTasksModel::LauncherUrlWithoutIcon).toUrl()) != -1) {
+        return {};
+    }
+
+    return concatProxyIndex.data(AbstractTasksModel::AppId).toString();
+}
+
+void TasksModel::Private::applyManualAppOrder()
+{
+    // Reorders the sort map entries of tasks found in manualAppOrder among
+    // themselves, leaving all other entries in place.
+
+    if (manualAppOrder.isEmpty()) {
+        return;
+    }
+
+    QList<int> positions;
+    QList<std::pair<qsizetype, int>> rankedRows;
+
+    for (int i = 0; i < sortedPreFilterRows.count(); ++i) {
+        const qsizetype rank = manualAppOrder.indexOf(manualAppOrderId(concatProxyModel->index(sortedPreFilterRows.at(i), 0)));
+
+        if (rank != -1) {
+            positions.append(i);
+            rankedRows.append({rank, sortedPreFilterRows.at(i)});
+        }
+    }
+
+    std::ranges::stable_sort(rankedRows, {}, &std::pair<qsizetype, int>::first);
+
+    for (int i = 0; i < positions.count(); ++i) {
+        sortedPreFilterRows[positions.at(i)] = rankedRows.at(i).second;
+    }
+}
+
+void TasksModel::Private::sortInByManualAppOrder(int concatProxyRow)
+{
+    // Moves a new task in front of the first task that comes after it in manualAppOrder.
+
+    const qsizetype rank = manualAppOrder.indexOf(manualAppOrderId(concatProxyModel->index(concatProxyRow, 0)));
+
+    if (rank == -1) {
+        return;
+    }
+
+    const qsizetype pos = sortedPreFilterRows.indexOf(concatProxyRow);
+
+    for (int i = 0; i < pos; ++i) {
+        const qsizetype otherRank = manualAppOrder.indexOf(manualAppOrderId(concatProxyModel->index(sortedPreFilterRows.at(i), 0)));
+
+        if (otherRank > rank) {
+            sortedPreFilterRows.move(pos, i);
+            break;
+        }
+    }
+}
+
+void TasksModel::Private::updateManualAppOrder()
+{
+    // Writes the current order of tasks to manualAppOrder, keeping installed
+    // apps that currently have no tasks after the app they followed before.
+    // Apps without tasks are dropped from the end once the list is too long.
+
+    QStringList order;
+
+    for (const int row : std::as_const(sortedPreFilterRows)) {
+        const QString appId = manualAppOrderId(concatProxyModel->index(row, 0));
+
+        if (!appId.isEmpty() && !order.contains(appId)) {
+            order.append(appId);
+        }
+    }
+
+    const QStringList openApps = order;
+    qsizetype insertPos = 0;
+
+    for (const QString &appId : std::as_const(manualAppOrder)) {
+        const qsizetype pos = order.indexOf(appId);
+
+        if (pos != -1) {
+            insertPos = pos + 1;
+        } else if (KService::serviceByDesktopName(appId)) {
+            order.insert(insertPos++, appId);
+        }
+    }
+
+    for (qsizetype i = order.count() - 1; i >= 0 && order.count() > maxManualAppOrder; --i) {
+        if (!openApps.contains(order.at(i))) {
+            order.removeAt(i);
+        }
+    }
+
+    if (order != manualAppOrder) {
+        manualAppOrder = order;
+        Q_EMIT q->manualAppOrderChanged();
+    }
+}
+
 void TasksModel::Private::updateGroupInline()
 {
     if (usedByQml && !componentComplete) {
@@ -1396,6 +1512,38 @@ void TasksModel::setLauncherList(const QStringList &launchers)
     d->launchersEverSet = true;
 }

+QStringList TasksModel::manualAppOrder() const
+{
+    return d->manualAppOrder;
+}
+
+void TasksModel::setManualAppOrder(const QStringList &appIds)
+{
+    if (d->manualAppOrder == appIds) {
+        return;
+    }
+
+    d->manualAppOrder = appIds;
+
+    if (d->sortMode == SortManual && !d->sortedPreFilterRows.isEmpty()) {
+        d->applyManualAppOrder();
+
+        if (groupMode() != GroupDisabled) {
+            for (int i = 0; i < d->groupingProxyModel->rowCount(); ++i) {
+                const QModelIndex &groupingIndex = d->groupingProxyModel->index(i, 0);
+
+                if (groupingIndex.data(AbstractTasksModel::IsGroupParent).toBool()) {
+                    d->consolidateManualSortMapForGroup(groupingIndex);
+                }
+            }
+        }
+
+        d->forceResort();
+    }
+
+    Q_EMIT manualAppOrderChanged();
+}
+
 bool TasksModel::requestAddLauncher(const QUrl &url)
 {
     d->initLauncherTasksModel();
@@ -1841,6 +1989,8 @@ bool TasksModel::move(int row, int newPos, const QModelIndex &parent)
         }
     }

+    d->updateManualAppOrder();
+
     // Setup for syncLaunchers().
     d->launcherSortingDirty = isLauncherMove;

